async function getWeather() {
  const urls = [
    'https://wttr.in/San%20Francisco?format=j1',
    'https://api.open-meteo.com/v1/forecast?latitude=37.7749&longitude=-122.4194&current=temperature_2m,weather_code,wind_speed_10m&timezone=auto'
  ];

  for (const url of urls) {
    try {
      const res = await fetch(url, { headers: { 'User-Agent': 'probe-sandbox' } });
      if (!res.ok) continue;
      const contentType = res.headers.get('content-type') || '';
      if (contentType.includes('application/json')) {
        const data = await res.json();
        return { source: url, data };
      } else {
        // try parse as text JSON fallback
        const text = await res.text();
        try {
          const data = JSON.parse(text);
          return { source: url, data };
        } catch {
          continue;
        }
      }
    } catch (err) {
      // try next
    }
  }
  return null;
}

